BookEdgePainterMaker.ironStock=12; BookEdgePainterMaker.bronzeStock=10; BookEdgePainterMaker.woodStock=14; BookEdgePainterMaker.leatherStock=10; BookEdgePainterMaker.silverStock=8; BookEdgePainterMaker.goldStock=6; BookEdgePainterMaker.jewelStock=4; BookEdgePainterMaker.pearlStock=4
BookEdgePainterMaker.productStock = {}; BookEdgePainterMaker.buildings = {}; BookEdgePainterMaker.maker = nil; BookEdgePainterMaker.activeMaking = {}; BookEdgePainterMaker.totalProducts = 0; BookEdgePainterMaker.dayTimer = 0
function BookEdgePainterMaker.init() BookEdgePainterMaker.ironStock=12; BookEdgePainterMaker.bronzeStock=10; BookEdgePainterMaker.woodStock=14; BookEdgePainterMaker.leatherStock=10; BookEdgePainterMaker.silverStock=8; BookEdgePainterMaker.goldStock=6; BookEdgePainterMaker.jewelStock=4; BookEdgePainterMaker.pearlStock=4; BookEdgePainterMaker.productStock={}; BookEdgePainterMaker.buildings={}; BookEdgePainterMaker.maker=nil; BookEdgePainterMaker.activeMaking={}; BookEdgePainterMaker.totalProducts=0; BookEdgePainterMaker.dayTimer=0; print("[BookEdgePainterMaker] Royal Book Edge Painter Maker System initialized (6 products, 4 buildings)") end
function BookEdgePainterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookEdgePainterMaker.maker={name=n or ("Roboslikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Roboslikar najet: %s (spretnost: %d)",BookEdgePainterMaker.maker.name,s),"success") end; return true end
function BookEdgePainterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookEdgePainterMaker.build(id) local ok,e=BookEdgePainterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookEdgePainterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookEdgePainterMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookEdgePainterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookEdgePainterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookEdgePainterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookEdgePainterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookEdgePainterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookEdgePainterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookEdgePainterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookEdgePainterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookEdgePainterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookEdgePainterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookEdgePainterMaker.buildings==0 then return false,"Potrebna roboslikarska delavnica" end; if not BookEdgePainterMaker.maker then return false,"Potreben roboslikar" end; return true end
function BookEdgePainterMaker.make(pt,qty) qty=qty or 1; local ok,e=BookEdgePainterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookEdgePainterMaker.ironStock=BookEdgePainterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookEdgePainterMaker.bronzeStock=BookEdgePainterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookEdgePainterMaker.woodStock=BookEdgePainterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookEdgePainterMaker.leatherStock=BookEdgePainterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookEdgePainterMaker.silverStock=BookEdgePainterMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookEdgePainterMaker.goldStock=BookEdgePainterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookEdgePainterMaker.jewelStock=BookEdgePainterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookEdgePainterMaker.pearlStock=BookEdgePainterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookEdgePainterMaker.maker then t=math.max(1,t-math.floor(BookEdgePainterMaker.maker.skill/13)) end; table.insert(BookEdgePainterMaker.activeMaking,{id="bookedgepainter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookEdgePainterMaker.completeMaking(m) local q=1.0+(BookEdgePainterMaker.getQualityBonus()/100); if BookEdgePainterMaker.maker then q=q+(BookEdgePainterMaker.maker.skill/140) end; q=math.min(2.5,q); BookEdgePainterMaker.productStock[m.productType]=(BookEdgePainterMaker.productStock[m.productType] or 0)+m.quantity; BookEdgePainterMaker.totalProducts=BookEdgePainterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookEdgePainterMaker.maker then BookEdgePainterMaker.maker.itemsMade=BookEdgePainterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookEdgePainterMaker.maker.skill=math.min(100,BookEdgePainterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Roboslikar izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookedgepainter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookEdgePainterMaker.update(dt) if not _G.state then return end; BookEdgePainterMaker.dayTimer=BookEdgePainterMaker.dayTimer+dt; if BookEdgePainterMaker.dayTimer>=30 then BookEdgePainterMaker.dayTimer=0; for i=#BookEdgePainterMaker.activeMaking,1,-1 do local m=BookEdgePainterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookEdgePainterMaker.completeMaking(m); table.remove(BookEdgePainterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookEdgePainterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookEdgePainterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookEdgePainterMaker.getStats() return {ironStock=BookEdgePainterMaker.ironStock,bronzeStock=BookEdgePainterMaker.bronzeStock,woodStock=BookEdgePainterMaker.woodStock,leatherStock=BookEdgePainterMaker.leatherStock,silverStock=BookEdgePainterMaker.silverStock,goldStock=BookEdgePainterMaker.goldStock,jewelStock=BookEdgePainterMaker.jewelStock,pearlStock=BookEdgePainterMaker.pearlStock,productStock=BookEdgePainterMaker.productStock,numBuildings=#BookEdgePainterMaker.buildings,hasMaker=BookEdgePainterMaker.maker~=nil,makerName=BookEdgePainterMaker.maker and BookEdgePainterMaker.maker.name or "—",makerSkill=BookEdgePainterMaker.maker and BookEdgePainterMaker.maker.skill or 0,activeMaking=#BookEdgePainterMaker.activeMaking,totalProducts=BookEdgePainterMaker.totalProducts} end
return BookEdgePainterMaker
